function maximumTop(nums, k) {
  const n = nums.length;
  if (n === 1 && k % 2 === 1) {
    return -1;
  }
  let best = -1;
  const removable = Math.min(k - 1, n);
  for (let i = 0; i < removable; i++) {
    best = Math.max(best, nums[i]);
  }
  if (k < n) {
    best = Math.max(best, nums[k]);
  }
  return best;
}

