function maximumTop(nums, k) {
  // A state is the pile itself, written as a string of element indices from the top down.
  // Layer t holds every pile reachable in exactly t moves.
  const n = nums.length;
  const next = (layer) => {
    const result = new Set();
    for (const pile of layer) {
      if (pile.length > 0) result.add(pile.slice(1));
      for (let i = 0; i < n; i++) {
        const id = String.fromCharCode(65 + i);
        if (!pile.includes(id)) result.add(id + pile);
      }
    }
    return result;
  };
  const same = (a, b) => a.size === b.size && [...a].every(p => b.has(p));
  let start = '';
  for (let i = 0; i < n; i++) start += String.fromCharCode(65 + i);
  const layers = [new Set([start])];
  let final = null;
  for (let t = 1; t <= k; t++) {
    layers.push(next(layers[t - 1]));
    // Once a layer repeats the one two moves earlier, the layers alternate forever.
    if (t >= 2 && same(layers[t], layers[t - 2])) {
      final = (k - t) % 2 === 0 ? layers[t] : layers[t - 1];
      break;
    }
  }
  if (final === null) final = layers[Math.min(k, layers.length - 1)];
  let best = -1;
  for (const pile of final) if (pile.length > 0) best = Math.max(best, nums[pile.charCodeAt(0) - 65]);
  return best;
}

