function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'small') {
    const n = pick(1, 5);
    const nums = Array.from({ length: n }, () => pick(0, 9));
    const r = rand();
    const k = r < 0.7 ? pick(0, n + 2) : r < 0.9 ? pick(0, 12) : pick(0, 1000000000);
    return [nums, k];
  }
  const n = 2000;
  const nums = Array.from({ length: n }, () => pick(0, 1000000000));
  const r = rand();
  const k = r < 0.4 ? pick(0, n - 1) : r < 0.6 ? n - 1 + pick(0, 2) : pick(n + 1, 1000000000);
  return [nums, k];
}
